package com.motionlayer.editor
import androidx.compose.foundation.*; import androidx.compose.foundation.gestures.detectTapGestures; import androidx.compose.foundation.layout.*; import androidx.compose.foundation.shape.RoundedCornerShape; import androidx.compose.material3.*; import androidx.compose.runtime.Composable; import androidx.compose.ui.*; import androidx.compose.ui.graphics.Color; import androidx.compose.ui.input.pointer.pointerInput; import androidx.compose.ui.unit.dp
import com.motionlayer.data.*
@Composable fun TimelineView(project:MotionLayerProject,timeMs:Long,onSeek:(Long)->Unit,onSelect:(String)->Unit){ val duration=project.mainVideo.durationMs.coerceAtLeast(1000); Column(Modifier.background(Color(0xff151515)).padding(8.dp)){ Text("%02d:%02d / %02d:%02d".format(timeMs/60000,(timeMs/1000)%60,duration/60000,(duration/1000)%60), color=Color.LightGray); Box(Modifier.fillMaxWidth().height(190.dp).horizontalScroll(rememberScrollState()).pointerInput(duration){ detectTapGestures{ onSeek(((it.x/1200f)*duration).toLong().coerceIn(0,duration)) }}){ Column(Modifier.width(1200.dp)){ Track("Main video",0,duration,Color.White); project.layers.sortedBy{it.zIndex}.forEach{ l-> Track(l.name,l.startTimeMs,l.endTimeMs, if(l.type==LayerType.TEXT) Color(0xff24d9ff) else Color(0xff7c5cff), l.keyframes){ onSelect(l.id) } }; Box(Modifier.offset(x=((timeMs.toFloat()/duration)*1200).dp).width(2.dp).fillMaxHeight().background(Color.White)) } } } }
@Composable private fun Track(name:String,start:Long,end:Long,color:Color,keys:List<Keyframe> = emptyList(),onClick:()->Unit={}){ Box(Modifier.height(42.dp).fillMaxWidth().padding(vertical=4.dp)){ Box(Modifier.offset(x=(start/10).dp).width(((end-start).coerceAtLeast(200)/10).dp).fillMaxHeight().clip(RoundedCornerShape(6.dp)).background(color).clickable{onClick()}.padding(8.dp)){ Text(name,color=if(color==Color.White) Color.Black else Color.White) }; keys.forEach{ Box(Modifier.offset(x=(it.timeMs/10).dp,y=12.dp).size(10.dp).background(Color.Yellow, RoundedCornerShape(50))) } } }
